def _cases(key: str, mutations: tuple[str, ...]) -> list[dict[str, str]]:
    assert len(mutations) == 6
    return [{"input": "", "setup_sql": _BASE + mutation, "expected_output": ORACLE_OUTPUTS[key][i]} for i, mutation in enumerate(mutations)]

def _item(number: int, title: str, difficulty: str, family: str, description: str, solution: str, hints: tuple[str, str, str], complexity: str, mutations: tuple[str, ...], schema: str) -> dict[str, Any]:
    key = f"sql-curated-{number:03d}"
    cases = _cases(key, mutations)
    return {"id": key, "title": title, "language": "sql", "difficulty": difficulty, "topics": [family], "curriculum_family": family, "practice_frequency": "Common", "description": description, "constraints": ["Write one read-only SELECT or WITH query in the selected dialect.", "The selected dialect is translated for local SQLite compatibility before judging.", "Return columns in exactly the requested order.", schema], "examples": [{"input": "", "output": cases[0]["expected_output"], "explanation": "The managed example illustrates the contract; hidden datasets alter the named edge conditions."}], "starter_code": STARTER, "solution": solution, "hints": list(hints), "expected_complexity": complexity, "public_tests": cases[:2], "hidden_tests": cases[2:], "sql_setup": cases[0]["setup_sql"]}

